fn eq(&self, other: &RangeMap<K, V>) -> bool {
    if self.btm.len() != other.btm.len() {
        return false;
    }

    self.btm
        .iter()
        .zip(other.btm.iter())
        .all(|((k1, v1), (k2, v2))| k1.start == k2.start && k1.end == k2.end && v1 == v2)
}

